<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';$user=Auth::requireLogin();if(isset($_GET['logout'])){Auth::logout();redirect('/admin/login.php');}
try{$pdo=Database::connection();$stats=[];
if(($user['role']??'')==='company_manager'){$cid=(int)($user['company_id']??0);$queries=['bookings'=>['SELECT COUNT(*) FROM bookings b JOIN trips t ON t.id=b.trip_id WHERE t.company_id=?',[$cid]],'new_bookings'=>["SELECT COUNT(*) FROM bookings b JOIN trips t ON t.id=b.trip_id WHERE t.company_id=? AND b.status='new'",[$cid]],'confirmed'=>["SELECT COUNT(*) FROM bookings b JOIN trips t ON t.id=b.trip_id WHERE t.company_id=? AND b.status='confirmed'",[$cid]],'trips'=>['SELECT COUNT(*) FROM trips WHERE company_id=?',[$cid]],'customers'=>['SELECT COUNT(DISTINCT b.customer_id) FROM bookings b JOIN trips t ON t.id=b.trip_id WHERE t.company_id=?',[$cid]]];foreach($queries as $key=>$item){$q=$pdo->prepare($item[0]);$q->execute($item[1]);$stats[$key]=$q->fetchColumn();}$stats['companies']=1;$stats['umrah']=$stats['services']='—';$q=$pdo->prepare('SELECT b.reference_code,b.status,b.passengers_count,b.created_at,c.full_name FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN trips t ON t.id=b.trip_id WHERE t.company_id=? ORDER BY b.id DESC LIMIT 8');$q->execute([$cid]);$latest=$q->fetchAll();}
else{$stats=['bookings'=>$pdo->query('SELECT COUNT(*) FROM bookings')->fetchColumn(),'new_bookings'=>$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='new'")->fetchColumn(),'confirmed'=>$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='confirmed'")->fetchColumn(),'trips'=>$pdo->query('SELECT COUNT(*) FROM trips')->fetchColumn(),'companies'=>$pdo->query("SELECT COUNT(*) FROM companies WHERE status='active'")->fetchColumn(),'customers'=>$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn(),'umrah'=>$pdo->query('SELECT COUNT(*) FROM umrah_requests')->fetchColumn(),'services'=>$pdo->query('SELECT COUNT(*) FROM service_requests')->fetchColumn()];$latest=$pdo->query('SELECT b.reference_code,b.status,b.passengers_count,b.created_at,c.full_name FROM bookings b JOIN customers c ON c.id=b.customer_id ORDER BY b.id DESC LIMIT 8')->fetchAll();}
}catch(Throwable $e){$stats=[];$latest=[];$error=$config['debug']?$e->getMessage():'تعذر تحميل بيانات لوحة التحكم.';}
$links=[['الرئيسية','/admin/index.php','dashboard.view'],['الرحلات','/admin/trips.php','trips.manage'],['الحجوزات','/admin/bookings.php','bookings.manage'],['الشركات','/admin/companies.php','companies.manage'],['برامج العمرة','/admin/catalog.php?type=umrah','umrah.manage'],['الخدمات','/admin/catalog.php?type=service','services.manage'],['طلبات العمرة والخدمات','/admin/requests.php','umrah.manage'],['الفروع','/admin/branches.php','companies.manage'],['الموظفون','/admin/users.php','users.manage'],['التقارير','/admin/reports.php','reports.view'],['العملاء','/admin/customers.php','customers.view'],['الأدوار والصلاحيات','/admin/roles.php','settings.manage'],['سجل النشاط','/admin/activity.php','settings.manage'],['الإعدادات','/admin/settings.php','settings.manage']];
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة التحكم | أصل المتصدر</title><link rel="stylesheet" href="/assets/css/app.css"><style>.admin-shell{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.sidebar{background:#10263f;color:#dbe4ed;padding:25px 18px}.sidebar .brand b{color:#fff}.side-links{display:grid;gap:7px;margin-top:30px}.side-links a{padding:10px;border-radius:8px;font-size:13px}.side-links a:hover,.side-links a.active{background:#ffffff18;color:#fff}.admin-main{padding:30px;min-width:0;background:#f6f8fa}.admin-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.admin-top h1{margin:0;color:#10263f}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat,.panel{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:18px}.stat small{color:#718092}.stat strong{display:block;font-size:28px;color:#10263f}.panel{margin-top:20px;overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:right;padding:11px;border-bottom:1px solid #edf0f3;font-size:13px}@media(max-width:760px){.admin-shell{grid-template-columns:1fr}.sidebar{padding:12px}.side-links{display:flex;overflow:auto;margin-top:12px}.side-links a{white-space:nowrap}.admin-main{padding:16px}.stats{grid-template-columns:repeat(2,1fr)}.admin-top{align-items:flex-start;gap:12px;flex-direction:column}}</style></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="/"><span class="brand-mark">م</span><span><b>أصل المتصدر</b><small>الإدارة المركزية</small></span></a><nav class="side-links"><?php foreach($links as [$label,$url,$permission]):if(Auth::can($permission)):?><a href="<?=e($url)?>"><?=e($label)?></a><?php endif;endforeach;?><a href="/admin/index.php?logout=1">تسجيل الخروج</a></nav></aside><main class="admin-main"><div class="admin-top"><div><span class="eyebrow">مساحة العمل</span><h1>مرحباً، <?=e($user['name'])?></h1></div><a class="btn btn-outline" href="/">عرض الموقع</a></div><?php if(isset($error)):?><p class="notice"><?=e($error)?></p><?php endif;?><div class="stats"><?php foreach(['bookings'=>'إجمالي الحجوزات','new_bookings'=>'حجوزات جديدة','confirmed'=>'حجوزات مؤكدة','trips'=>'الرحلات','companies'=>'شركات النقل','customers'=>'العملاء','umrah'=>'طلبات العمرة','services'=>'طلبات الخدمات'] as $key=>$label):?><div class="stat"><small><?=e($label)?></small><strong><?=e($stats[$key]??'—')?></strong></div><?php endforeach;?></div><section class="panel"><h2>أحدث الحجوزات</h2><table><thead><tr><th>رقم الطلب</th><th>العميل</th><th>المسافرون</th><th>الحالة</th><th>تاريخ الطلب</th></tr></thead><tbody><?php foreach($latest as $row):?><tr><td><?=e($row['reference_code'])?></td><td><?=e($row['full_name'])?></td><td><?=(int)$row['passengers_count']?></td><td><?=e($row['status'])?></td><td><?=e($row['created_at'])?></td></tr><?php endforeach;?><?php if(!$latest):?><tr><td colspan="5">لا توجد حجوزات حتى الآن.</td></tr><?php endif;?></tbody></table></section></main></div></body></html>